INSERT INTO blog_post_translations
  (post_id, locale, slug, title, excerpt, body_html, seo_title, seo_description)
VALUES (
  :post_id, 'uz', $x$honkai-star-rail-toldirish$x$,
  $x$Honkai: Star Rail: qanday toʻldirish va nima sotib olish$x$,
  $x$Honkai: Star Rail’ni Oʻzbekistondan UID orqali toʻldirish: Oneiric Shards va Stellar Jade farqi, yangi oʻyinchiga nima foydali va ikki baravar bonus qanday ishlaydi.$x$,
$x$<h2>Asosiysi</h2>
<ul>
<li>Honkai: Star Rail UID va server orqali toʻldiriladi. Parol kerak emas.</li>
<li>Pulga Oneiric Shards sotib olinadi. Ular Stellar Jade’ga birga-bir almashadi, bitta warp esa 160 jade turadi.</li>
<li>Yangi oʻyinchi uchun eng foydalisi Express Supply Pass: darhol 300 Shards va 30 kun ichida yana 2700 jade.</li>
<li>Har bir Shards nominalining birinchi xaridi ikki baravar beriladi. Har bir nominal alohida ikki baravar boʻladi.</li>
</ul>
<p>Quyida oʻyin valyutalari, boshida nima olish kerakligi va akkauntni soʻmda toʻlab qanday toʻldirish haqida.</p>
<h2>Oneiric Shards, Stellar Jade va Express Supply Pass</h2>
<p>Valyutalar zanjir boʻlib ishlaydi. Pulga Oneiric Shards olinadi. Shards Stellar Jade’ga birga-bir almashadi. Jade warp’larga sarflanadi — personajlar va Light Cone’lar oʻyini.</p>
<ul>
<li><strong>Oneiric Shards.</strong> Pullik valyuta. Jade’ga almashtiriladi yoki oʻyin doʻkonidagi toʻplamlarga sarflanadi.</li>
<li><strong>Stellar Jade.</strong> Warp valyutasi. Topshiriqlar, tadbirlar va yutuqlar uchun beriladi, Shards’dan ham olinadi. Bitta warp 160 jade turadi.</li>
<li><strong>Express Supply Pass.</strong> 30 kunlik obuna: darhol 300 Shards va oʻyinga kirgan har bir kun uchun 90 jade.</li>
</ul>
<p>Warp’larda hisoblang. Banner uchun nechta warp kerakligini aniqlang va 160 ga koʻpaytiring — bu kerakli jade. Shunda summani oldindan bilasiz va koʻr-koʻrona qoʻshimcha sotib olmaysiz.</p>
<p>Genshin Impact’da ham shunday, faqat valyutalar boshqacha nomlanadi. Bu haqda <a href="/uz/blog/genshin-impact-genesis-kristallari">Genshin Impact’dagi Genesis kristallari</a> qoʻllanmasida yozilgan.</p>
<h2>Yangi oʻyinchiga nima foydali</h2>
<p>Har kuni oʻyinga kirsangiz, Express Supply Pass’dan boshlang. U 330 Shards paketi bilan deyarli bir xil turadi, lekin bir oyda 3000 gacha beradi: darhol 300 Shards va kuniga 90 tadan 2700 jade. Oʻtkazib yuborilgan kun — yoʻqotilgan 90 jade, ular yigʻilmaydi.</p>
<p>Keyin — Shards paketlaridagi ikki baravar bonus. Har bir nominalning birinchi xaridi ikki baravar koʻp beradi. Bonus har bir nominal uchun alohida hisoblanadi, shuning uchun tartib muhim emas: kichik paket kattasining bonusini «yoqib» yubormaydi. Kerakli warp’larni yopadigan nominalni oling.</p>
<p>Qisqacha tartib:</p>
<ul>
<li>Har kuni oʻynasangiz — Express Supply Pass.</li>
<li>Ikki baravar bonusi hali ishlatilmagan Shards nominali.</li>
<li>Oddiy paketlar — bonuslar ishlatib boʻlingach.</li>
</ul>
<h2>YuPay orqali Honkai: Star Rail’ni UID bilan toʻldirish</h2>
<p><a href="/uz/store/honkai-star-rail">Honkai: Star Rail sahifasida</a> Oneiric Shards — 60, 330, 1090, 2240, 3880 va 8080 — hamda Express Supply Pass sotiladi.</p>
<ol>
<li>UID’ni toping. U oʻyin bosh ekranining pastki chap burchagida koʻrsatiladi.</li>
<li>Serverni aniqlang: America, Asia, Europe yoki TW/HK/MO. U kirish ekranida koʻrinadi. Oʻzbekistondagi oʻyinchilar koʻpincha Europe’da.</li>
<li>Nominalni tanlang, UID va serverni kiriting. Ikkala maydonni qayta tekshiring.</li>
<li>Click, Payme yoki Uzum orqali toʻlang. Soʻmdagi yakuniy summa toʻlovdan oldin koʻrinadi va aynan u yechiladi.</li>
</ol>
<p>Valyuta toʻlov tasdiqlangach avtomatik tushadi. Akkauntga kirish va parol kerak emas: hech kimga kirish huquqini bermaysiz.</p>
<p>PlayStation’da oʻynaysizmi? Xuddi shu HoYoverse akkaunti bilan telefon yoki kompyuterda oʻyinga kiring: xarid konsol profiliga emas, akkauntga tushadi.</p>
<h2>Ikki baravar bonus: qanday qoʻldan boy bermaslik</h2>
<p>U shunday ishlaydi. 60 Shards’ni birinchi marta oldingiz — 60 uchun ikki baravar oldingiz. 1090 ni birinchi marta oldingiz — 1090 uchun ikki baravar. Xuddi shu nominalni qayta olsangiz, oddiy miqdor beriladi.</p>
<p>Ikki baravarni oʻyinning oʻzi beradi. HoYoverse uni vaqti-vaqti bilan, odatda yirik yangilanishlarga qadar qayta tiklaydi. Agar bu siz kutayotgan bannerga toʻgʻri kelsa, sotib olish uchun eng yaxshi payt.</p>
<p>Adashmaslik uchun ikki baravar ishlatilgan nominallarni belgilab qoʻying.</p>
<h2>Koʻp uchraydigan xatolar</h2>
<ul>
<li><strong>Notoʻgʻri UID yoki server.</strong> Valyuta boshqa akkauntga ketadi, uni qaytarish deyarli imkonsiz. Toʻlovdan oldin ikkala maydonni tekshiring.</li>
<li><strong>Login va parol soʻraydigan sotuvchilar.</strong> Akkauntlar aynan shunday yoʻqotiladi. Toʻldirish uchun UID yetarli.</li>
<li><strong>Esdan chiqqan Express Supply Pass.</strong> Jade faqat oʻyinga kirgan kunlaringiz beriladi.</li>
</ul>
<p>Ishonchli servisni qanday ajratish <a href="/uz/blog/oyin-valyutasini-xavfsiz-sotib-olish">oʻyin valyutasini xavfsiz sotib olish</a> maqolasida yozilgan.</p>
<h2>Nimadan boshlash kerak</h2>
<p>UID va serverni toping, nechta warp kerakligini hisoblang va <a href="/uz/store/honkai-star-rail">YuPay’da Honkai: Star Rail</a> sahifasini oching. Har kuni oʻynasangiz, Express Supply Pass’dan boshlang.</p>$x$,
  $x$Honkai: Star Rail’ni UID orqali toʻldirish — nima olish kerak$x$,
  $x$Honkai: Star Rail’ni UID va server orqali parolsiz toʻldirish. Oneiric Shards, Stellar Jade va Express Supply Pass: avval nima olish kerak. Toʻlov soʻmda.$x$
);

